import { loadData, data, searchChannels } from '../../api'
import { Collection, Logger } from '@freearhey/core'
import { select, input } from '@inquirer/prompts'
import { Playlist, Stream } from '../../models'
import { Storage } from '@freearhey/storage-js'
import { PlaylistParser } from '../../core'
import { ROOT_DIR } from '../../constants'
import { truncate } from '../../utils'
import nodeCleanup from 'node-cleanup'
import * as sdk from '@iptv-org/sdk'
import { Command } from 'commander'
import readline from 'readline'
import path from 'node:path'

type ChoiceValue = { type: string; value?: sdk.Models.Feed | sdk.Models.Channel }
type Choice = { name: string; short?: string; value: ChoiceValue; default?: boolean }

if (process.platform === 'win32') {
  readline
    .createInterface({
      input: process.stdin,
      output: process.stdout
    })
    .on('SIGINT', function () {
      process.emit('SIGINT')
    })
}

const program = new Command()

program.argument('<filepath>', 'Path to *.channels.xml file to edit').parse(process.argv)

const filepath = program.args[0]
const logger = new Logger()

const resolvedPath = path.resolve(filepath)
const relative = path.relative(ROOT_DIR, resolvedPath)
if (relative.startsWith('..') || path.isAbsolute(relative)) {
  console.error(`Error: filepath "${filepath}" is outside the working directory`)
  process.exit(1)
}

const storage = new Storage()
let parsedStreams = new Collection<Stream>()

main(filepath)
nodeCleanup(() => {
  save(filepath)
})

export default async function main(filepath: string) {
  if (!(await storage.exists(filepath))) {
    throw new Error(`File "${filepath}" does not exists`)
  }

  logger.info('loading data from api...')
  await loadData()

  logger.info('loading streams...')
  const parser = new PlaylistParser({
    storage
  })
  parsedStreams = await parser.parseFile(filepath)
  const streamsWithoutId = parsedStreams.filter((stream: Stream) => !stream.tvgId)

  logger.info(
    `found ${parsedStreams.count()} streams (including ${streamsWithoutId.count()} without ID)`
  )

  logger.info('starting...\n')

  for (const stream of streamsWithoutId.all()) {
    try {
      stream.tvgId = await selectChannel(stream)
    } catch (err) {
      logger.info(err.message)
      break
    }
  }

  streamsWithoutId.forEach((stream: Stream) => {
    if (stream.tvgId === '-') {
      stream.tvgId = ''
    }
  })
}

async function selectChannel(stream: Stream): Promise<string> {
  const similarChannels = searchChannels(stream.title)
  const url = truncate(stream.url, 50)

  const selected: ChoiceValue = await select({
    message: `Select channel ID for "${stream.title}" (${url}):`,
    choices: getChannelChoises(similarChannels),
    pageSize: 10
  })

// check-quality validates PR body links and repository quality against
// CONTRIBUTING.md minimum standards. It outputs a markdown report and
// labels via GITHUB_OUTPUT for the PR Quality Checks workflow.
//
// Checks performed:
//   - Repo accessible, not archived, has go.mod and SemVer release
//   - Open source license present
//   - Repository age >= 5 months
//   - CI/CD (GitHub Actions) configured
//   - README exists
//   - Go Report Card grade A- or better
//   - pkg.go.dev page reachable
//   - Coverage link reachable
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"regexp"
	"strings"
	"time"
)

var (
	reForgeLink  = regexp.MustCompile(`(?i)forge\s+link[^:]*:\s*(https?://(?:github\.com|gitlab\.com|bitbucket\.org)/\S+)`)
	rePkgGoDev   = regexp.MustCompile(`(?i)pkg\.go\.dev:\s*(https?://pkg\.go\.dev/\S+)`)
	reGoReport   = regexp.MustCompile(`(?i)goreportcard\.com:\s*(https?://goreportcard\.com/\S+)`)
	reCoverage   = regexp.MustCompile(`(?i)coverage[^:]*:\s*(https?://(?:coveralls\.io|(?:app\.)?codecov\.io)/\S+)`)
	reGrade      = regexp.MustCompile(`(?i)Grade:\s*([A-F][+-]?)`)
	reGithubRepo = regexp.MustCompile(`^https?://github\.com/([^/]+)/([^/]+?)(?:\.git)?/?$`)
	reSemver     = regexp.MustCompile(`^v\d+\.\d+\.\d+`)
)

type prEvent struct {
	PullRequest struct {
		Body string `json:"body"`
	} `json:"pull_request"`
}

type repoData struct {
	Archived bool `json:"archived"`
	License  *struct {
		SPDXID string `json:"spdx_id"`
		Name   string `json:"name"`
	} `json:"license"`
	Message string `json:"message"` // present on API errors
}

type contentEntry struct {
	Name string `json:"name"`
}

type tagEntry struct {
	Name string `json:"name"`
}

type workflowsResponse struct {
	TotalCount int `json:"total_count"`
}

func main() {
	event := readEvent()
	body := event.PullRequest.Body

	forgeLink := captureMatch(body, reForgeLink)
	pkgLink := captureMatch(body, rePkgGoDev)
	gorepLink := captureMatch(body, reGoReport)
	covLink := captureMatch(body, reCoverage)

	var (
		critical     []string
		warnings     []string
		criticalFail bool
		repoOk       bool
		pkgOk        bool
		gorepOk      bool
		coverageOk   bool
		labels       []string
	)

	// --- Repo checks ---
	if forgeLink == "" {
		critical = append(critical, icon(false)+" **Repo link**: missing from PR body")
		critical = append(critical, fix("Add the following to your PR description:", "```\nForge link: https://github.com/your-org/your-project\n```"))
		criticalFail = true
	} else {
		r := checkGithubRepo(forgeLink)
		if !r.ok {
			critical = append(critical, fmt.Sprintf("%s **Repo**: %s", icon(false), r.reason))
			critical = append(critical, repoFixMessage(r.reason, forgeLink))
			criticalFail = true
		} else {
			critical = append(critical, icon(true)+" **Repo**: accessible, has go.mod and SemVer release")
			repoOk = true
		}

